begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000008801','note-owner@example.invalid'),('00000000-0000-4000-8000-000000008802','note-partner@example.invalid'),('00000000-0000-4000-8000-000000008803','note-other@example.invalid'),('00000000-0000-4000-8000-000000008804','note-device@example.invalid');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000008801','Synthetic','00000000-0000-4000-8000-000000008801'),('10000000-0000-4000-8000-000000008803','Other','00000000-0000-4000-8000-000000008803');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000008801','00000000-0000-4000-8000-000000008801'),('10000000-0000-4000-8000-000000008801','00000000-0000-4000-8000-000000008802'),('10000000-0000-4000-8000-000000008803','00000000-0000-4000-8000-000000008803');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000008801','10000000-0000-4000-8000-000000008801','Ece',5),('20000000-0000-4000-8000-000000008803','10000000-0000-4000-8000-000000008803','Other',5);
insert into public.devices(id,family_id,auth_user_id,active_child_id) values('60000000-0000-4000-8000-000000008804','10000000-0000-4000-8000-000000008801','00000000-0000-4000-8000-000000008804','20000000-0000-4000-8000-000000008801');
create function pg_temp.ch() returns uuid language sql as $$select '20000000-0000-4000-8000-000000008801'::uuid$$;
create function pg_temp.note() returns uuid language sql as $$select '30000000-0000-4000-8000-000000008801'::uuid$$;
create function pg_temp.value(v text default 'private',b text default 'New private content') returns jsonb language sql as $$select jsonb_build_object('title','Not başlığı','body',b,'subject','Matematik','visibility',v)$$;
create function pg_temp.actor(id text,role_name text default 'parent') returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',id,'role','authenticated','gina',jsonb_build_object('family_id',case when id like '%8803' then '10000000-0000-4000-8000-000000008803' else '10000000-0000-4000-8000-000000008801' end,'role',role_name,'device_id',case when role_name='device' then '60000000-0000-4000-8000-000000008804' else null end,'child_id',case when role_name='device' then pg_temp.ch() else null end))::text,true)$$;
set local role authenticated;
select pg_temp.actor('00000000-0000-4000-8000-000000008801');
insert into public.notes(id,family_id,child_id,author_user_id,title,body,visibility) values(pg_temp.note(),'10000000-0000-4000-8000-000000008801',pg_temp.ch(),'00000000-0000-4000-8000-000000008801','Private','Original secret','private');
select is((select count(*)::int from public.notes),1,'author sees personal note');
select pg_temp.actor('00000000-0000-4000-8000-000000008802');
select is((select count(*)::int from public.notes),0,'co-parent cannot read personal note');
select is((select count(*)::int from public.note_sync),0,'private edit does not notify co-parent');
select throws_ok($$select public.note_history(pg_temp.note())$$,'42501','forbidden','co-parent cannot read private history');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),1,'save',pg_temp.ch(),pg_temp.value())$$,'42501','forbidden','co-parent cannot alter personal note');
select pg_temp.actor('00000000-0000-4000-8000-000000008801');
select is((public.save_parent_note('40000000-0000-4000-8000-000000008801',pg_temp.note(),1,'save',pg_temp.ch(),pg_temp.value('family','Shared current content'))->>'revision')::int,2,'author shares edited current content');
select is((public.save_parent_note('40000000-0000-4000-8000-000000008801',pg_temp.note(),1,'save',pg_temp.ch(),pg_temp.value('family','Shared current content'))->>'revision')::int,2,'lost response retry one revision');
select is(public.note_history(pg_temp.note())->'rows'->0->'before_value'->>'body','Original secret','author history preserves private text');
select pg_temp.actor('00000000-0000-4000-8000-000000008802');
select is((select body from public.notes where id=pg_temp.note()),'Shared current content','co-parent sees only current shared text');
select is((select count(*)::int from public.note_sync),1,'sharing notifies co-parent');
select throws_ok($$select public.note_history(pg_temp.note())$$,'42501','forbidden','sharing never reveals earlier private history');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),2,'archive',pg_temp.ch())$$,'42501','forbidden','co-parent cannot archive author note');
with changed as(update public.notes set body='Bypass' where id=pg_temp.note() returning *) select is(count(*)::int,0,'co-parent direct update has no matching policy') from changed;
select pg_temp.actor('00000000-0000-4000-8000-000000008801');
select lives_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),2,'save',pg_temp.ch(),pg_temp.value('child','For the child'))$$,'share with linked child');
select pg_temp.actor('00000000-0000-4000-8000-000000008804','device');
select is((select body from public.notes where id=pg_temp.note()),'For the child','paired child sees current shared text');
select throws_ok($$select public.note_history(pg_temp.note())$$,'42501','forbidden','child cannot read earlier private history');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),3,'archive',pg_temp.ch())$$,'42501','forbidden','child cannot change parent note');
select pg_temp.actor('00000000-0000-4000-8000-000000008801');
select lives_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),3,'archive',pg_temp.ch())$$,'author archives');
select is((select count(*)::int from public.notes),1,'author can read own archive');
select pg_temp.actor('00000000-0000-4000-8000-000000008804','device');
select is((select count(*)::int from public.notes),0,'archive disappears from child');
select pg_temp.actor('00000000-0000-4000-8000-000000008802');
select is((select count(*)::int from public.notes),0,'archive disappears from co-parent');
select pg_temp.actor('00000000-0000-4000-8000-000000008801');
select is((public.save_parent_note(gen_random_uuid(),pg_temp.note(),4,'restore',pg_temp.ch())->>'revision')::int,5,'restore one revision');
select is((select visibility::text from public.notes where id=pg_temp.note()),'private','restoration never silently re-shares');
select is((select body from public.notes where id=pg_temp.note()),'For the child','restore keeps content');
select is(public.note_history(pg_temp.note())->'rows'->0->>'action','restore','restore single event');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),3,'save',pg_temp.ch(),pg_temp.value())$$,'P0001','note_changed','stale tab rejected');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),5,'save',pg_temp.ch(),pg_temp.value('private',''))$$,'P0001','note_invalid','empty content rejected');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),null,null,'save',null,pg_temp.value('child'))$$,'P0001','note_child_required','child share requires child');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),null,null,'save','20000000-0000-4000-8000-000000008803',pg_temp.value())$$,'42501','forbidden','foreign child rejected');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),5,'save',pg_temp.ch(),pg_temp.value()||'{"author_user_id":"x"}')$$,'P0001','note_invalid','extra identity fields rejected');
select throws_ok($$delete from public.notes where id=pg_temp.note()$$,'42501',null,'direct permanent deletion blocked');
select lives_ok($$select public.save_parent_note('40000000-0000-4000-8000-000000008802',null,null,'save',null,pg_temp.value())$$,'create general note');
select lives_ok($$select public.save_parent_note('40000000-0000-4000-8000-000000008802',null,null,'save',null,pg_temp.value())$$,'retry create');
select is((select count(*)::int from public.notes),2,'retry no duplicate note');
select lives_ok($$select public.set_child_archived(gen_random_uuid(),pg_temp.ch(),0,true)$$,'archive linked profile');
select throws_ok($$select public.save_parent_note(gen_random_uuid(),pg_temp.note(),5,'save',pg_temp.ch(),pg_temp.value())$$,'P0001','child_archived','profile archive blocks editing');
select lives_ok($$select public.note_history(pg_temp.note())$$,'profile archive preserves reading history');
select pg_temp.actor('00000000-0000-4000-8000-000000008803');
select is((select count(*)::int from public.notes),0,'foreign family has no note access');
select throws_ok($$select public.note_history(pg_temp.note())$$,'42501','forbidden','foreign family history denied');
reset role;
select ok(not has_function_privilege('anon','public.save_parent_note(uuid,uuid,integer,text,uuid,jsonb)','execute'),'anonymous write denied');
select ok(not has_table_privilege('authenticated','gina.note_changes','select'),'history table private');
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000008801'$$,'account deletion removes owned notes even with archived profile');
select is((select count(*)::int from gina.note_changes),0,'account deletion removes history');
select * from finish();rollback;
